package cli

import (
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"

	"github.com/spf13/cobra"
)

// trailAgentHelp is the "why/when" guide printed by `entire trail --agent-help`.
//
// Unlike normal --help (which a human reads to recall flags they already know
// they want), this is written for an agent that has no prior context about what
// a trail is or when to reach for one. It maps user intent -> command.
const trailAgentHelp = `Entire trails — agent guide

WHAT
  A trail is a branch-centric record of the "why" and "what" of a piece of
  work. Checkpoints capture the "how" and "when" (edits over time); a trail
  captures intent, decisions, and review findings for the branch. Trails live
  on the Entire server, keyed by forge/owner/repo + branch.

WHEN TO USE WHICH COMMAND
  User intent                                   Command
  -----------------------------------------     ------------------------------
  "open / start / create a trail"               entire trail create
  "add these findings to the trail"             entire trail finding add
  "show / what's the trail for this branch"     entire trail
  "list trails"                                 entire trail list
  "update the trail title / description"        entire trail update
  "show finding <id>"                           entire trail finding show <id>
  "apply that finding's suggested fix"          entire trail finding apply <id>
  "watch findings as they arrive"               entire trail finding watch

NOTES FOR AGENTS
  - The trail is resolved from the CURRENT git branch automatically, so for
    "the trail for this branch" you usually don't pass a trail number.
  - Typical review flow: you review a branch, the user says "add these findings
    to the trail" -> call 'entire trail finding add' (once per finding).
  - 'entire trail list --json' returns machine-readable output for chaining.
  - These commands require an authenticated session ('entire auth status').
`

// Marker-delimited managed block installed into agents' user-global memory
// files (e.g. ~/.claude/CLAUDE.md). The block is a SHORT intent->command
// pointer that is always loaded into the agent's context; it deliberately
// defers the full guide to `entire trail --agent-help` to keep token cost low.
const (
	trailGuideStartMarker = "<!-- ENTIRE-MANAGED TRAILS GUIDE v1 START -->"
	trailGuideEndMarker    = "<!-- ENTIRE-MANAGED TRAILS GUIDE v1 END -->"
)

var trailAgentGuideBlock = strings.Join([]string{
	trailGuideStartMarker,
	"## Entire trails",
	"",
	`Trails track the "why/what" of a branch's work, separate from git history.`,
	"When the user asks to:",
	"",
	"- **open / start / create a trail** → run `entire trail create`",
	"- **add review findings to a branch** (e.g. after reviewing it) → run " +
		"`entire trail finding add` (the trail is resolved from the current branch)",
	"- **show / view the current trail** → run `entire trail`",
	"",
	"For the full intent→command guide, run `entire trail --agent-help`.",
	trailGuideEndMarker,
}, "\n")

func printTrailAgentHelp(w io.Writer) error {
	_, err := io.WriteString(w, trailAgentHelp)
	return err
}

// upsertManagedBlock returns existing with the managed block inserted or
// refreshed. If the markers are already present, the region between them
// (inclusive) is replaced; otherwise the block is appended. Content outside the
// markers is preserved verbatim so the agent's other memory is never clobbered.
func upsertManagedBlock(existing []byte, block string) []byte {
	text := string(existing)
	start := strings.Index(text, trailGuideStartMarker)
	end := strings.Index(text, trailGuideEndMarker)
	if start >= 0 && end >= start {
		endClose := end + len(trailGuideEndMarker)
		return []byte(text[:start] + block + text[endClose:])
	}
	if len(text) == 0 {
		return []byte(block + "\n")
	}
	if !strings.HasSuffix(text, "\n") {
		text += "\n"
	}
	return []byte(text + "\n" + block + "\n")
}

type trailGuideTarget struct {
	Agent types.AgentName
	Dir   string // parent dir; must exist (unless --all) before we write
	Path  string // memory file to upsert the managed block into
}

// trailAgentGuideTargets lists the user-global memory file per agent that has a
// well-defined one. Kept pure (home passed in) so tests never touch real $HOME.
func trailAgentGuideTargets(home string) []trailGuideTarget {
	return []trailGuideTarget{
		{types.AgentNameClaudeCode, filepath.Join(home, ".claude"), filepath.Join(home, ".claude", "CLAUDE.md")},
		{types.AgentNameCodex, filepath.Join(home, ".codex"), filepath.Join(home, ".codex", "AGENTS.md")},
		{types.AgentNameGemini, filepath.Join(home, ".gemini"), filepath.Join(home, ".gemini", "GEMINI.md")},
	}
}

type trailGuideInstallStatus string

const (
	trailGuideCreated     trailGuideInstallStatus = "created"
	trailGuideUpdated     trailGuideInstallStatus = "updated"
	trailGuideUnchanged   trailGuideInstallStatus = "unchanged"
	trailGuideSkippedNo​Dir trailGuideInstallStatus = "skipped (agent not set up)"
)

type trailGuideInstallResult struct {
	Target trailGuideTarget
	Status trailGuideInstallStatus
}

// installTrailAgentGuide upserts the managed pointer block into each known
// agent memory file under home. By default it only writes for agents whose
// config dir already exists; --all writes (and creates dirs) for every target.
// --dry-run computes the would-be status without writing.
func installTrailAgentGuide(home string, all, dryRun bool) ([]trailGuideInstallResult, error) {
	var results []trailGuideInstallResult
	for _, t := range trailAgentGuideTargets(home) {
		if !all {
			if _, err := os.Stat(t.Dir); errors.Is(err, os.ErrNotExist) {
				results = append(results, trailGuideInstallResult{Target: t, Status: trailGuideSkippedNoDir})
				continue
			} else if err != nil {
				return nil, fmt.Errorf("stat %s: %w", t.Dir, err)
			}
		}

		existing, err := os.ReadFile(t.Path) //nolint:gosec // path derived from home + fixed agent-relative names
		switch {
		case err == nil:
		case errors.Is(err, os.ErrNotExist):
			existing = nil
		default:
			return nil, fmt.Errorf("read %s: %w", t.Path, err)
		}

		updated := upsertManagedBlock(existing, trailAgentGuideBlock)
		if existing != nil && string(updated) == string(existing) {
			results = append(results, trailGuideInstallResult{Target: t, Status: trailGuideUnchanged})
			continue
		}

		status := trailGuideUpdated
		if existing == nil {
			status = trailGuideCreated
		}
		if !dryRun {
			if err := os.MkdirAll(t.Dir, 0o750); err != nil {
				return nil, fmt.Errorf("create %s: %w", t.Dir, err)
			}
			if err := os.WriteFile(t.Path, updated, 0o600); err != nil {
				return nil, fmt.Errorf("write %s: %w", t.Path, err)
			}
		}
		results = append(results, trailGuideInstallResult{Target: t, Status: status})
	}
	return results, nil
}

func newTrailInstallGuideCmd() *cobra.Command {
	var all, dryRun bool
	cmd := &cobra.Command{
		Use:   "install-agent-guide",
		Short: "Install the trails intent→command pointer into agents' global memory",
		Long: `Install a small managed block into each AI agent's user-global memory file
(e.g. ~/.claude/CLAUDE.md, ~/.codex/AGENTS.md, ~/.gemini/GEMINI.md) so that an
agent in ANY repository knows when to reach for 'entire trail' commands.

The block is marker-delimited and conflict-safe: re-running refreshes only the
managed region and never touches the rest of the file. By default only agents
whose config directory already exists are written; use --all to write to every
known agent.`,
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			home, err := os.UserHomeDir()
			if err != nil {
				return fmt.Errorf("resolve home directory: %w", err)
			}
			results, err := installTrailAgentGuide(home, all, dryRun)
			if err != nil {
				return err
			}
			w := cmd.OutOrStdout()
			if dryRun {
				fmt.Fprintln(w, "Dry run — no files written.")
			}
			for _, r := range results {
				fmt.Fprintf(w, "  %-12s %s (%s)\n", r.Target.Agent, r.Target.Path, r.Status)
			}
			return nil
		},
	}
	cmd.Flags().BoolVar(&all, "all", false, "Write to every known agent, creating its config dir if needed")
	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "Show what would change without writing")
	return cmd
}

