package cli

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestPrintTrailAgentHelp_CoversIntents(t *testing.T) {
	t.Parallel()

	var sb strings.Builder
	if err := printTrailAgentHelp(&sb); err != nil {
		t.Fatalf("printTrailAgentHelp: %v", err)
	}
	out := sb.String()
	for _, want := range []string{
		"entire trail create",
		"entire trail finding add",
		"resolved from the CURRENT git branch",
		"--json",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("agent help missing %q\n---\n%s", want, out)
		}
	}
}

func TestUpsertManagedBlock_AppendsWhenAbsent(t *testing.T) {
	t.Parallel()

	existing := []byte("# My memory\n\nSome personal notes.\n")
	got := string(upsertManagedBlock(existing, trailAgentGuideBlock))

	if !strings.HasPrefix(got, "# My memory") {
		t.Errorf("existing content not preserved at top:\n%s", got)
	}
	if !strings.Contains(got, "Some personal notes.") {
		t.Errorf("existing body lost:\n%s", got)
	}
	if !strings.Contains(got, trailGuideStartMarker) || !strings.Contains(got, trailGuideEndMarker) {
		t.Errorf("managed block markers missing:\n%s", got)
	}
}

func TestUpsertManagedBlock_EmptyFile(t *testing.T) {
	t.Parallel()

	got := string(upsertManagedBlock(nil, trailAgentGuideBlock))
	if !strings.HasPrefix(got, trailGuideStartMarker) {
		t.Errorf("empty file should start with the block:\n%s", got)
	}
	if !strings.HasSuffix(got, "\n") {
		t.Errorf("block should end with a trailing newline:\n%q", got)
	}
}

func TestUpsertManagedBlock_ReplacesInPlacePreservingSurroundings(t *testing.T) {
	t.Parallel()

	before := "# Top\n\n"
	after := "\n## Footer\n\nkeep me\n"
	stale := before + trailGuideStartMarker + "\nOLD OUTDATED CONTENT\n" + trailGuideEndMarker + after

	got := string(upsertManagedBlock([]byte(stale), trailAgentGuideBlock))

	if strings.Contains(got, "OLD OUTDATED CONTENT") {
		t.Errorf("stale managed content not replaced:\n%s", got)
	}
	if !strings.HasPrefix(got, before) {
		t.Errorf("content before block not preserved:\n%s", got)
	}
	if !strings.HasSuffix(got, after) {
		t.Errorf("content after block not preserved:\n%s", got)
	}
	if strings.Count(got, trailGuideStartMarker) != 1 {
		t.Errorf("expected exactly one managed block, got:\n%s", got)
	}
}

func TestInstallTrailAgentGuide_OnlyExistingDirsByDefault(t *testing.T) {
	t.Parallel()

	home := t.TempDir()
	// Set up only Claude; leave Codex/Gemini absent.
	claudeDir := filepath.Join(home, ".claude")
	if err := os.MkdirAll(claudeDir, 0o750); err != nil {
		t.Fatal(err)
	}

	results, err := installTrailAgentGuide(home, false, false)
	if err != nil {
		t.Fatalf("installTrailAgentGuide: %v", err)
	}

	statuses := map[types_AgentNameProxy]trailGuideInstallStatus{}
	for _, r := range results {
		statuses[types_AgentNameProxy(r.Target.Agent)] = r.Status
	}
	if statuses["claude-code"] != trailGuideCreated {
		t.Errorf("claude-code: want created, got %q", statuses["claude-code"])
	}
	if statuses["codex"] != trailGuideSkippedNoDir {
		t.Errorf("codex: want skipped, got %q", statuses["codex"])
	}

	data, err := os.ReadFile(filepath.Join(claudeDir, "CLAUDE.md"))
	if err != nil {
		t.Fatalf("read CLAUDE.md: %v", err)
	}
	if !strings.Contains(string(data), trailGuideStartMarker) {
		t.Errorf("CLAUDE.md missing managed block:\n%s", data)
	}

	// Codex dir must not have been created.
	if _, err := os.Stat(filepath.Join(home, ".codex")); !os.IsNotExist(err) {
		t.Errorf("codex dir should not be created without --all")
	}
}

func TestInstallTrailAgentGuide_Idempotent(t *testing.T) {
	t.Parallel()

	home := t.TempDir()
	if _, err := installTrailAgentGuide(home, true, false); err != nil {
		t.Fatalf("first install: %v", err)
	}
	results, err := installTrailAgentGuide(home, true, false)
	if err != nil {
		t.Fatalf("second install: %v", err)
	}
	for _, r := range results {
		if r.Status != trailGuideUnchanged {
			t.Errorf("%s: re-run want unchanged, got %q", r.Target.Agent, r.Status)
		}
	}
}

func TestInstallTrailAgentGuide_DryRunWritesNothing(t *testing.T) {
	t.Parallel()

	home := t.TempDir()
	results, err := installTrailAgentGuide(home, true, true)
	if err != nil {
		t.Fatalf("installTrailAgentGuide: %v", err)
	}
	for _, r := range results {
		if r.Status != trailGuideCreated {
			t.Errorf("%s: dry-run on empty home want created, got %q", r.Target.Agent, r.Status)
		}
		if _, err := os.Stat(r.Target.Path); !os.IsNotExist(err) {
			t.Errorf("dry-run wrote file %s", r.Target.Path)
		}
	}
}

