type trailGuideInstallStatus string

const (
	trailGuideCreated      trailGuideInstallStatus = "created"
	trailGuideUpdated      trailGuideInstallStatus = "updated"
	trailGuideUnchanged    trailGuideInstallStatus = "unchanged"
	trailGuideSkippedNoDir trailGuideInstallStatus = "skipped (agent not set up)"
)

type trailGuideInstallResult struct {
	Target trailGuideTarget
	Status trailGuideInstallStatus
}

// installTrailAgentGuide upserts the managed pointer block into each known
// agent memory file under home. By default it only writes for agents whose
// config dir already exists; --all writes (and creates dirs) for every target.
// --dry-run computes the would-be status without writing.
func installTrailAgentGuide(home string, all, dryRun bool) ([]trailGuideInstallResult, error) {
	var results []trailGuideInstallResult
	for _, t := range trailAgentGuideTargets(home) {
		if !all {
			if _, err := os.Stat(t.Dir); errors.Is(err, os.ErrNotExist) {
				results = append(results, trailGuideInstallResult{Target: t, Status: trailGuideSkippedNoDir})
				continue
			} else if err != nil {
				return nil, fmt.Errorf("stat %s: %w", t.Dir, err)
			}
		}

		existing, err := os.ReadFile(t.Path) //nolint:gosec // path derived from home + fixed agent-relative names
		switch {
		case err == nil:
		case errors.Is(err, os.ErrNotExist):
			existing = nil
		default:
			return nil, fmt.Errorf("read %s: %w", t.Path, err)
		}

		updated := upsertManagedBlock(existing, trailAgentGuideBlock)
		if existing != nil && string(updated) == string(existing) {
			results = append(results, trailGuideInstallResult{Target: t, Status: trailGuideUnchanged})
			continue
		}

		status := trailGuideUpdated
		if existing == nil {
			status = trailGuideCreated
		}
		if !dryRun {
			if err := os.MkdirAll(t.Dir, 0o750); err != nil {
				return nil, fmt.Errorf("create %s: %w", t.Dir, err)
			}
			if err := os.WriteFile(t.Path, updated, 0o600); err != nil {
				return nil, fmt.Errorf("write %s: %w", t.Path, err)
			}
		}
		results = append(results, trailGuideInstallResult{Target: t, Status: status})
	}
	return results, nil
}

func newTrailInstallGuideCmd() *cobra.Command {
	var all, dryRun bool
	cmd := &cobra.Command{
		Use:   "install-agent-guide",
		Short: "Install the trails intent→command pointer into agents' global memory",
		Long: `Install a small managed block into each AI agent's user-global memory file
(e.g. ~/.claude/CLAUDE.md, ~/.codex/AGENTS.md, ~/.gemini/GEMINI.md) so that an
agent in ANY repository knows when to reach for 'entire trail' commands.

The block is marker-delimited and conflict-safe: re-running refreshes only the
managed region and never touches the rest of the file. By default only agents
whose config directory already exists are written; use --all to write to every
known agent.`,
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			home, err := os.UserHomeDir()
			if err != nil {
				return fmt.Errorf("resolve home directory: %w", err)
			}
			results, err := installTrailAgentGuide(home, all, dryRun)
			if err != nil {
				return err
			}
			w := cmd.OutOrStdout()
			if dryRun {
				fmt.Fprintln(w, "Dry run — no files written.")
			}
			for _, r := range results {
				fmt.Fprintf(w, "  %-12s %s (%s)\n", r.Target.Agent, r.Target.Path, r.Status)
			}
			return nil
		},
	}
	cmd.Flags().BoolVar(&all, "all", false, "Write to every known agent, creating its config dir if needed")
	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "Show what would change without writing")
	return cmd
}

