package cli

import (
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// entireManagedAgentGuideSkillMarker tags the agent-guide skill file as
// Entire-owned so re-running `enable` refreshes it but never clobbers a
// hand-authored file at the same path.
const entireManagedAgentGuideSkillMarker = "ENTIRE-MANAGED AGENT GUIDE SKILL v1"

type agentGuideSkillResult struct {
	Status  managedScaffoldStatus
	RelPath string
	// Supported is false for agents that have no skill mechanism; nothing is
	// installed and nothing is reported for them.
	Supported bool
}

// scaffoldAgentGuideSkill installs a thin, stable "pointer" skill that tells
// the agent to consult `entire --agent-help` for current, version-accurate
// usage. The skill carries no command details, so it never needs updating when
// the CLI changes — the authoritative guidance lives in the binary.
func scaffoldAgentGuideSkill(ctx context.Context, ag agent.Agent) (agentGuideSkillResult, error) {
	relPath, content, ok := agentGuideSkillTemplate(ag.Name())
	if !ok {
		return agentGuideSkillResult{Supported: false}, nil
	}

	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails in tests
		if err != nil {
			return agentGuideSkillResult{}, fmt.Errorf("failed to get current directory: %w", err)
		}
	}

	targetPath := filepath.Join(repoRoot, relPath)
	status, err := writeManagedFile(targetPath, content, entireManagedAgentGuideSkillMarker)
	if err != nil {
		return agentGuideSkillResult{}, err
	}
	return agentGuideSkillResult{Status: status, RelPath: relPath, Supported: true}, nil
}

func reportAgentGuideSkillScaffold(w io.Writer, ag agent.Agent, result agentGuideSkillResult) {
	if !result.Supported {
		return
	}
	switch result.Status {
	case managedScaffoldCreated:
		fmt.Fprintf(w, "  ✓ Installed %s Entire skill\n", ag.Type())
		fmt.Fprintf(w, "    %s\n", result.RelPath)
	case managedScaffoldUpdated:
		fmt.Fprintf(w, "  ✓ Updated %s Entire skill\n", ag.Type())
		fmt.Fprintf(w, "    %s\n", result.RelPath)
	case managedScaffoldSkippedConflict:
		fmt.Fprintf(w, "  Skipped %s Entire skill (unmanaged file exists)\n", ag.Type())
		fmt.Fprintf(w, "    %s\n", result.RelPath)
	case managedScaffoldUnchanged:
		// Nothing to report.
	}
}

// agentGuideSkillTemplate returns the repo-relative path and content of the
// pointer skill for an agent, or ok=false when the agent has no skill mechanism.
// Skills are currently a Claude Code feature; other agents already receive the
// search subagent and can gain a guide artifact when their format is supported.
func agentGuideSkillTemplate(agentName types.AgentName) (string, []byte, bool) {
	switch agentName {
	case agent.AgentNameClaudeCode:
		return filepath.Join(".claude", "skills", "entire", "SKILL.md"),
			[]byte(strings.TrimSpace(claudeAgentGuideSkillTemplate) + "\n"), true
	default:
		return "", nil, false
	}
}

const claudeAgentGuideSkillTemplate = `
---
name: entire
description: Use the Entire CLI (` + "`entire`" + `) for trails, checkpoints, and review findings. Trigger when the user asks to open/start/create a trail, add review findings to a branch's trail, or otherwise work with Entire trails, checkpoints, or session history.
---

<!-- ` + entireManagedAgentGuideSkillMarker + ` -->

The Entire CLI (` + "`entire`" + `) is installed in this environment and is the
source of truth for its own current, agent-oriented usage. This skill is a thin
pointer on purpose: it never lists commands or flags, so it stays correct across
CLI versions. Always read the live guidance from the binary rather than relying
on cached knowledge.

When the user wants to work with Entire — for example:

- "open / start / create a trail"
- "add these findings to the trail for this branch"
- anything about trails, checkpoints, or session/review history

first run:

    entire --agent-help

That prints an index of agent-oriented command guides. Drill into a specific
command for its why/when guidance, e.g.:

    entire trail --agent-help

Then run the appropriate ` + "`entire`" + ` command directly. If a command needs
authentication, ` + "`entire auth status`" + ` reports login state.
`

