package cli

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/agent/codex"
)

// Note: these use setupTestDir (t.Chdir), so they cannot run t.Parallel().

func TestScaffoldAgentGuideSkill_CreatesPointerSkill(t *testing.T) {
	tmpDir := setupTestDir(t)

	ag := claudecode.NewClaudeCodeAgent()
	result, err := scaffoldAgentGuideSkill(context.Background(), ag)
	if err != nil {
		t.Fatalf("scaffoldAgentGuideSkill() error = %v", err)
	}
	if !result.Supported {
		t.Fatal("claude-code should support the agent-guide skill")
	}
	if result.Status != managedScaffoldCreated {
		t.Fatalf("status = %q, want %q", result.Status, managedScaffoldCreated)
	}

	want := filepath.Join(".claude", "skills", "entire", "SKILL.md")
	if result.RelPath != want {
		t.Fatalf("RelPath = %q, want %q", result.RelPath, want)
	}

	data, err := os.ReadFile(filepath.Join(tmpDir, result.RelPath))
	if err != nil {
		t.Fatalf("read SKILL.md: %v", err)
	}
	content := string(data)
	// The pointer must direct agents to the binary, and must NOT bake in
	// command specifics that would go stale (it points, it does not duplicate).
	if !strings.Contains(content, "entire --agent-help") {
		t.Errorf("skill should point at `entire --agent-help`:\n%s", content)
	}
	if !strings.Contains(content, entireManagedAgentGuideSkillMarker) {
		t.Errorf("skill missing managed marker:\n%s", content)
	}
}

func TestScaffoldAgentGuideSkill_Idempotent(t *testing.T) {
	setupTestDir(t)

	ag := claudecode.NewClaudeCodeAgent()
	if _, err := scaffoldAgentGuideSkill(context.Background(), ag); err != nil {
		t.Fatalf("first scaffold: %v", err)
	}
	result, err := scaffoldAgentGuideSkill(context.Background(), ag)
	if err != nil {
		t.Fatalf("second scaffold: %v", err)
	}
	if result.Status != managedScaffoldUnchanged {
		t.Fatalf("re-run status = %q, want %q", result.Status, managedScaffoldUnchanged)
	}
}

func TestScaffoldAgentGuideSkill_PreservesUserOwnedFile(t *testing.T) {
	tmpDir := setupTestDir(t)

	ag := claudecode.NewClaudeCodeAgent()
	relPath, _, ok := agentGuideSkillTemplate(ag.Name())
	if !ok {
		t.Fatal("agentGuideSkillTemplate() unexpectedly unsupported for claude")
	}
	targetPath := filepath.Join(tmpDir, relPath)
	if err := os.MkdirAll(filepath.Dir(targetPath), 0o750); err != nil {
		t.Fatalf("mkdir: %v", err)
	}
	userContent := "my hand-written skill\n"
	if err := os.WriteFile(targetPath, []byte(userContent), 0o600); err != nil {
		t.Fatalf("write: %v", err)
	}

	result, err := scaffoldAgentGuideSkill(context.Background(), ag)
	if err != nil {
		t.Fatalf("scaffoldAgentGuideSkill() error = %v", err)
	}
	if result.Status != managedScaffoldSkippedConflict {
		t.Fatalf("status = %q, want %q", result.Status, managedScaffoldSkippedConflict)
	}
	data, err := os.ReadFile(targetPath)
	if err != nil {
		t.Fatalf("read: %v", err)
	}
	if string(data) != userContent {
		t.Fatal("user-owned skill file must not be overwritten")
	}
}

func TestScaffoldAgentGuideSkill_UnsupportedAgent(t *testing.T) {
	setupTestDir(t)

	ag := codex.NewCodexAgent()
	result, err := scaffoldAgentGuideSkill(context.Background(), ag)
	if err != nil {
		t.Fatalf("scaffoldAgentGuideSkill() error = %v", err)
	}
	if result.Supported {
		t.Fatal("codex should report the skill as unsupported (no skill mechanism yet)")
	}
}

